foreach (var typeDefHandle in mr.TypeDefinitions) {
    var typeDef = mr.GetTypeDefinition(typeDefHandle);
    var name = mr.GetString(typeDef.Name);
    if (name == "ITestCaseOrderer") {
        var ns = mr.GetString(typeDef.Namespace);
        Console.WriteLine($"Interface: {ns}.{name}");
        foreach (var methodHandle in typeDef.GetMethods()) {
            var method = mr.GetMethodDefinition(methodHandle);
            Console.WriteLine($"  Method: {mr.GetString(method.Name)}");
            var sig = method.DecodeSignature(new SignatureTypeProvider(), null);
            Console.WriteLine($"    Return: {sig.ReturnType}");
            foreach (var p in sig.ParameterTypes)
                Console.WriteLine($"    Param: {p}");
        }
    }
}

class SignatureTypeProvider : ISignatureTypeProvider<string, object?> {
    public string GetPrimitiveType(PrimitiveTypeCode typeCode) => typeCode.ToString();
    public string GetTypeFromDefinition(MetadataReader r, TypeDefinitionHandle h, byte rawTypeKind) { var td = r.GetTypeDefinition(h); return $"{r.GetString(td.Namespace)}.{r.GetString(td.Name)}"; }
    public string GetTypeFromReference(MetadataReader r, TypeReferenceHandle h, byte rawTypeKind) { var tr = r.GetTypeReference(h); return $"{r.GetString(tr.Namespace)}.{r.GetString(tr.Name)}"; }
    public string GetSZArrayType(string elementType) => $"{elementType}[]";
    public string GetGenericInstantiation(string genericType, System.Collections.Immutable.ImmutableArray<string> typeArguments) => $"{genericType}<{string.Join(", ", typeArguments)}>";
    public string GetArrayType(string elementType, ArrayShape shape) => $"{elementType}[{shape.Rank}]";
    public string GetByReferenceType(string elementType) => $"ref {elementType}";
    public string GetPointerType(string elementType) => $"{elementType}*";
    public string GetFunctionPointerType(MethodSignature<string> signature) => "fnptr";
    public string GetGenericMethodParameter(object? gc, int i) => $"!!{i}";
    public string GetGenericTypeParameter(object? gc, int i) => $"!{i}";
    public string GetModifiedType(string modifier, string unmodifiedType, bool isRequired) => unmodifiedType;
    public string GetPinnedType(string elementType) => elementType;
    public string GetTypeFromSpecification(MetadataReader r, object? gc, TypeSpecificationHandle h, byte rawTypeKind) => "TypeSpec";
}
